34|static lzma_ret
35|auto_decode(void *coder_ptr, const lzma_allocator *allocator,
36|		const uint8_t *restrict in, size_t *restrict in_pos,
37|		size_t in_size, uint8_t *restrict out,
38|		size_t *restrict out_pos, size_t out_size, lzma_action action)
39|{
40|	lzma_auto_coder *coder = coder_ptr;
41|
42|	switch (coder->sequence) {
43|	case SEQ_INIT:
44|		if (*in_pos >= in_size)
45|			return LZMA_OK;
46|
47|		// Update the sequence now, because we want to continue from
48|		// SEQ_CODE even if we return some LZMA_*_CHECK.
49|		coder->sequence = SEQ_CODE;
50|
51|		// Detect the file format. .xz files start with 0xFD which
52|		// cannot be the first byte of .lzma (LZMA_Alone) format.
53|		// The .lz format starts with 0x4C which could be the
54|		// first byte of a .lzma file but luckily it would mean
55|		// lc/lp/pb being 4/3/1 which liblzma doesn't support because
56|		// lc + lp > 4. So using just 0x4C to detect .lz is OK here.
57|		if (in[*in_pos] == 0xFD) {
58|			return_if_error(lzma_stream_decoder_init(
59|					&coder->next, allocator,
60|					coder->memlimit, coder->flags));
61|#ifdef HAVE_LZIP_DECODER
62|		} else if (in[*in_pos] == 0x4C) {
63|			return_if_error(lzma_lzip_decoder_init(
64|					&coder->next, allocator,
65|					coder->memlimit, coder->flags));
66|#endif
67|		} else {
68|			return_if_error(lzma_alone_decoder_init(&coder->next,
69|					allocator, coder->memlimit, true));
70|
71|			// If the application wants to know about missing
72|			// integrity check or about the check in general, we
73|			// need to handle it here, because LZMA_Alone decoder
74|			// doesn't accept any flags.
75|			if (coder->flags & LZMA_TELL_NO_CHECK)
76|				return LZMA_NO_CHECK;
77|
78|			if (coder->flags & LZMA_TELL_ANY_CHECK)
79|				return LZMA_GET_CHECK;
80|		}
81|
82|		FALLTHROUGH;
83|
84|	case SEQ_CODE: {
85|		const lzma_ret ret = coder->next.code(
86|				coder->next.coder, allocator,
87|				in, in_pos, in_size,
88|				out, out_pos, out_size, action);
89|		if (ret != LZMA_STREAM_END
90|				|| (coder->flags & LZMA_CONCATENATED) == 0)
91|			return ret;
92|
93|		coder->sequence = SEQ_FINISH;
94|		FALLTHROUGH;
95|	}
96|
97|	case SEQ_FINISH:
98|		// When LZMA_CONCATENATED was used and we were decoding
99|		// a LZMA_Alone file, we need to check that there is no
100|		// trailing garbage and wait for LZMA_FINISH.
101|		if (*in_pos < in_size)
102|			return LZMA_DATA_ERROR;
103|
104|		return action == LZMA_FINISH ? LZMA_STREAM_END : LZMA_OK;
105|
106|	default:
107|		assert(0);
108|		return LZMA_PROG_ERROR;
109|	}
110|}

77|static lzma_ret
78|alone_encoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
79|		const lzma_options_lzma *options)
80|{
81|	lzma_next_coder_init(&alone_encoder_init, next, allocator);
82|
83|	lzma_alone_coder *coder = next->coder;
84|
85|	if (coder == NULL) {
86|		coder = lzma_alloc(sizeof(lzma_alone_coder), allocator);
87|		if (coder == NULL)
88|			return LZMA_MEM_ERROR;
89|
90|		next->coder = coder;
91|		next->code = &alone_encode;
92|		next->end = &alone_encoder_end;
93|		coder->next = LZMA_NEXT_CODER_INIT;
94|	}
95|
96|	// Basic initializations
97|	coder->sequence = SEQ_HEADER;
98|	coder->header_pos = 0;
99|
100|	// Encode the header:
101|	// - Properties (1 byte)
102|	if (lzma_lzma_lclppb_encode(options, coder->header))
103|		return LZMA_OPTIONS_ERROR;
104|
105|	// - Dictionary size (4 bytes)
106|	if (options->dict_size < LZMA_DICT_SIZE_MIN)
107|		return LZMA_OPTIONS_ERROR;
108|
109|	// Round up to the next 2^n or 2^n + 2^(n - 1) depending on which
110|	// one is the next unless it is UINT32_MAX. While the header would
111|	// allow any 32-bit integer, we do this to keep the decoder of liblzma
112|	// accepting the resulting files.
113|	uint32_t d = options->dict_size - 1;
114|	d |= d >> 2;
115|	d |= d >> 3;
116|	d |= d >> 4;
117|	d |= d >> 8;
118|	d |= d >> 16;
119|	if (d != UINT32_MAX)
120|		++d;
121|
122|	write32le(coder->header + 1, d);
123|
124|	// - Uncompressed size (always unknown and using EOPM)
125|	memset(coder->header + 1 + 4, 0xFF, 8);
126|
127|	// Initialize the LZMA encoder.
128|	const lzma_filter_info filters[2] = {
129|		{
130|			.id = LZMA_FILTER_LZMA1,
131|			.init = &lzma_lzma_encoder_init,
132|			.options = (void *)(options),
133|		}, {
134|			.init = NULL,
135|		}
136|	};
137|
138|	return lzma_next_filter_init(&coder->next, allocator, filters);
139|}

297|extern lzma_ret
298|lzma_raw_coder_init(lzma_next_coder *next, const lzma_allocator *allocator,
299|		const lzma_filter *options,
300|		lzma_filter_find coder_find, bool is_encoder)
301|{
302|	// Do some basic validation and get the number of filters.
303|	size_t count;
304|	return_if_error(lzma_validate_chain(options, &count));
305|
306|	// Set the filter functions and copy the options pointer.
307|	lzma_filter_info filters[LZMA_FILTERS_MAX + 1];
308|	if (is_encoder) {
309|		for (size_t i = 0; i < count; ++i) {
310|			// The order of the filters is reversed in the
311|			// encoder. It allows more efficient handling
312|			// of the uncompressed data.
313|			const size_t j = count - i - 1;
314|
315|			const lzma_filter_coder *const fc
316|					= coder_find(options[i].id);
317|			if (fc == NULL || fc->init == NULL)
318|				return LZMA_OPTIONS_ERROR;
319|
320|			filters[j].id = options[i].id;
321|			filters[j].init = fc->init;
322|			filters[j].options = options[i].options;
323|		}
324|	} else {
325|		for (size_t i = 0; i < count; ++i) {
326|			const lzma_filter_coder *const fc
327|					= coder_find(options[i].id);
328|			if (fc == NULL || fc->init == NULL)
329|				return LZMA_OPTIONS_ERROR;
330|
331|			filters[i].id = options[i].id;
332|			filters[i].init = fc->init;
333|			filters[i].options = options[i].options;
334|		}
335|	}
336|
337|	// Terminate the array.
338|	filters[count].id = LZMA_VLI_UNKNOWN;
339|	filters[count].init = NULL;
340|
341|	// Initialize the filters.
342|	const lzma_ret ret = lzma_next_filter_init(next, allocator, filters);
343|	if (ret != LZMA_OK)
344|		lzma_next_end(next, allocator);
345|
346|	return ret;
347|}

94|static lzma_ret
95|lzip_decode(void *coder_ptr, const lzma_allocator *allocator,
96|		const uint8_t *restrict in, size_t *restrict in_pos,
97|		size_t in_size, uint8_t *restrict out,
98|		size_t *restrict out_pos, size_t out_size, lzma_action action)
99|{
100|	lzma_lzip_coder *coder = coder_ptr;
101|
102|	while (true)
103|	switch (coder->sequence) {
104|	case SEQ_ID_STRING: {
105|		// The "ID string" or magic bytes are "LZIP" in US-ASCII.
106|		const uint8_t lzip_id_string[4] = { 0x4C, 0x5A, 0x49, 0x50 };
107|
108|		while (coder->pos < sizeof(lzip_id_string)) {
109|			if (*in_pos >= in_size) {
110|				// If we are on the 2nd+ concatenated member
111|				// and the input ends before we can read
112|				// the magic bytes, we discard the bytes that
113|				// were already read (up to 3) and finish.
114|				// See the reasoning below.
115|				return !coder->first_member
116|						&& action == LZMA_FINISH
117|					? LZMA_STREAM_END : LZMA_OK;
118|			}
119|
120|			if (in[*in_pos] != lzip_id_string[coder->pos]) {
121|				// The .lz format allows putting non-.lz data
122|				// at the end of the file. If we have seen
123|				// at least one valid .lz member already,
124|				// then we won't consume the byte at *in_pos
125|				// and will return LZMA_STREAM_END. This way
126|				// apps can easily locate and read the non-.lz
127|				// data after the .lz member(s).
128|				//
129|				// NOTE: If the first 1-3 bytes of the non-.lz
130|				// data match the .lz ID string then the first
131|				// 1-3 bytes of the junk will get ignored by
132|				// us. If apps want to properly locate the
133|				// trailing data they must ensure that the
134|				// first byte of their custom data isn't the
135|				// same as the first byte of .lz ID string.
136|				// With the liblzma API we cannot rewind the
137|				// input position across calls to lzma_code().
138|				return !coder->first_member
139|					? LZMA_STREAM_END : LZMA_FORMAT_ERROR;
140|			}
141|
142|			++*in_pos;
143|			++coder->pos;
144|		}
145|
146|		coder->pos = 0;
147|
148|		coder->crc32 = 0;
149|		coder->uncompressed_size = 0;
150|		coder->member_size = sizeof(lzip_id_string);
151|
152|		coder->sequence = SEQ_VERSION;
153|		FALLTHROUGH;
154|	}
155|
156|	case SEQ_VERSION:
157|		if (*in_pos >= in_size)
158|			return LZMA_OK;
159|
160|		coder->version = in[(*in_pos)++];
161|
162|		// We support version 0 and unextended version 1.
163|		if (coder->version > 1)
164|			return LZMA_OPTIONS_ERROR;
165|
166|		++coder->member_size;
167|		coder->sequence = SEQ_DICT_SIZE;
168|
169|		// .lz versions 0 and 1 use CRC32 as the integrity check
170|		// so if the application wanted to know that
171|		// (LZMA_TELL_ANY_CHECK) we can tell it now.
172|		if (coder->tell_any_check)
173|			return LZMA_GET_CHECK;
174|
175|		FALLTHROUGH;
176|
177|	case SEQ_DICT_SIZE: {
178|		if (*in_pos >= in_size)
179|			return LZMA_OK;
180|
181|		const uint32_t ds = in[(*in_pos)++];
182|		++coder->member_size;
183|
184|		// The five lowest bits are for the base-2 logarithm of
185|		// the dictionary size and the highest three bits are
186|		// the fractional part (0/16 to 7/16) that will be
187|		// subtracted to get the final value.
188|		//
189|		// For example, with 0xB5:
190|		//     b2log = 21
191|		//     fracnum = 5
192|		//     dict_size = 2^21 - 2^21 * 5 / 16 = 1408 KiB
193|		const uint32_t b2log = ds & 0x1F;
194|		const uint32_t fracnum = ds >> 5;
195|
196|		// The format versions 0 and 1 allow dictionary size in the
197|		// range [4 KiB, 512 MiB].
198|		if (b2log < 12 || b2log > 29 || (b2log == 12 && fracnum > 0))
199|			return LZMA_DATA_ERROR;
200|
201|		//   2^[b2log] - 2^[b2log] * [fracnum] / 16
202|		// = 2^[b2log] - [fracnum] * 2^([b2log] - 4)
203|		coder->options.dict_size = (UINT32_C(1) << b2log)
204|				- (fracnum << (b2log - 4));
205|
206|		assert(coder->options.dict_size >= 4096);
207|		assert(coder->options.dict_size <= (UINT32_C(512) << 20));
208|
209|		coder->options.preset_dict = NULL;
210|		coder->options.lc = LZIP_LC;
211|		coder->options.lp = LZIP_LP;
212|		coder->options.pb = LZIP_PB;
213|
214|		// Calculate the memory usage.
215|		coder->memusage
216|			= lzma_lzma_decoder_memusage_nocheck(&coder->options)
217|				+ LZMA_MEMUSAGE_BASE;
218|
219|		// Initialization is a separate step because if we return
220|		// LZMA_MEMLIMIT_ERROR we need to be able to restart after
221|		// the memlimit has been increased.
222|		coder->sequence = SEQ_CODER_INIT;
223|		FALLTHROUGH;
224|	}
225|
226|	case SEQ_CODER_INIT: {
227|		if (coder->memusage > coder->memlimit)
228|			return LZMA_MEMLIMIT_ERROR;
229|
230|		const lzma_filter_info filters[2] = {
231|			{
232|				.id = LZMA_FILTER_LZMA1,
233|				.init = &lzma_lzma_decoder_init,
234|				.options = &coder->options,
235|			}, {
236|				.init = NULL,
237|			}
238|		};
239|
240|		return_if_error(lzma_next_filter_init(&coder->lzma_decoder,
241|				allocator, filters));
242|
243|		coder->crc32 = 0;
244|		coder->sequence = SEQ_LZMA_STREAM;
245|		FALLTHROUGH;
246|	}
247|
248|	case SEQ_LZMA_STREAM: {
249|		const size_t in_start = *in_pos;
250|		const size_t out_start = *out_pos;
251|
252|		const lzma_ret ret = coder->lzma_decoder.code(
253|				coder->lzma_decoder.coder, allocator,
254|				in, in_pos, in_size, out, out_pos, out_size,
255|				action);
256|
257|		const size_t out_used = *out_pos - out_start;
258|
259|		coder->member_size += *in_pos - in_start;
260|		coder->uncompressed_size += out_used;
261|
262|		// Don't update the CRC32 if the integrity check will be
263|		// ignored or if there was no new output. The latter is
264|		// important in case out == NULL to avoid null pointer + 0
265|		// which is undefined behavior.
266|		if (!coder->ignore_check && out_used > 0)
267|			coder->crc32 = lzma_crc32(out + out_start, out_used,
268|					coder->crc32);
269|
270|		if (ret != LZMA_STREAM_END)
271|			return ret;
272|
273|		coder->sequence = SEQ_MEMBER_FOOTER;
274|		FALLTHROUGH;
275|	}
276|
277|	case SEQ_MEMBER_FOOTER: {
278|		// The footer of .lz version 0 lacks the Member size field.
279|		// This is the only difference between version 0 and
280|		// unextended version 1 formats.
281|		const size_t footer_size = coder->version == 0
282|				? LZIP_V0_FOOTER_SIZE
283|				: LZIP_V1_FOOTER_SIZE;
284|
285|		// Copy the CRC32, Data size, and Member size fields to
286|		// the internal buffer.
287|		lzma_bufcpy(in, in_pos, in_size, coder->buffer, &coder->pos,
288|				footer_size);
289|
290|		// Return if we didn't get the whole footer yet.
291|		if (coder->pos < footer_size)
292|			return LZMA_OK;
293|
294|		coder->pos = 0;
295|		coder->member_size += footer_size;
296|
297|		// Check that the footer fields match the observed data.
298|		if (!coder->ignore_check
299|				&& coder->crc32 != read32le(&coder->buffer[0]))
300|			return LZMA_DATA_ERROR;
301|
302|		if (coder->uncompressed_size != read64le(&coder->buffer[4]))
303|			return LZMA_DATA_ERROR;
304|
305|		if (coder->version > 0) {
306|			// .lz version 0 has no Member size field.
307|			if (coder->member_size != read64le(&coder->buffer[12]))
308|				return LZMA_DATA_ERROR;
309|		}
310|
311|		// Decoding is finished if we weren't requested to decode
312|		// more than one .lz member.
313|		if (!coder->concatenated)
314|			return LZMA_STREAM_END;
315|
316|		coder->first_member = false;
317|		coder->sequence = SEQ_ID_STRING;
318|		break;
319|	}
320|
321|	default:
322|		assert(0);
323|		return LZMA_PROG_ERROR;
324|	}
325|
326|	// Never reached
327|}

47|static lzma_ret
48|microlzma_decode(void *coder_ptr, const lzma_allocator *allocator,
49|		const uint8_t *restrict in, size_t *restrict in_pos,
50|		size_t in_size, uint8_t *restrict out,
51|		size_t *restrict out_pos, size_t out_size, lzma_action action)
52|{
53|	lzma_microlzma_coder *coder = coder_ptr;
54|
55|	// Remember the in start position so that we can update comp_size.
56|	const size_t in_start = *in_pos;
57|
58|	// Remember the out start position so that we can update uncomp_size.
59|	const size_t out_start = *out_pos;
60|
61|	// Limit the amount of input so that the decoder won't read more than
62|	// comp_size. This is required when uncomp_size isn't exact because
63|	// in that case the LZMA decoder will try to decode more input even
64|	// when it has no output space (it can be looking for EOPM).
65|	if (in_size - *in_pos > coder->comp_size)
66|		in_size = *in_pos + (size_t)(coder->comp_size);
67|
68|	// When the exact uncompressed size isn't known, we must limit
69|	// the available output space to prevent the LZMA decoder from
70|	// trying to decode too much.
71|	if (!coder->uncomp_size_is_exact
72|			&& out_size - *out_pos > coder->uncomp_size)
73|		out_size = *out_pos + (size_t)(coder->uncomp_size);
74|
75|	if (!coder->props_decoded) {
76|		// There must be at least one byte of input to decode
77|		// the properties byte.
78|		if (*in_pos >= in_size)
79|			return LZMA_OK;
80|
81|		lzma_options_lzma options = {
82|			.dict_size = coder->dict_size,
83|			.preset_dict = NULL,
84|			.preset_dict_size = 0,
85|			.ext_flags = 0, // EOPM not allowed when size is known
86|			.ext_size_low = UINT32_MAX, // Unknown size by default
87|			.ext_size_high = UINT32_MAX,
88|		};
89|
90|		if (coder->uncomp_size_is_exact)
91|			lzma_set_ext_size(options, coder->uncomp_size);
92|
93|		// The properties are stored as bitwise-negation
94|		// of the typical encoding.
95|		if (lzma_lzma_lclppb_decode(&options, ~in[*in_pos]))
96|			return LZMA_OPTIONS_ERROR;
97|
98|		++*in_pos;
99|
100|		// Initialize the decoder.
101|		lzma_filter_info filters[2] = {
102|			{
103|				.id = LZMA_FILTER_LZMA1EXT,
104|				.init = &lzma_lzma_decoder_init,
105|				.options = &options,
106|			}, {
107|				.init = NULL,
108|			}
109|		};
110|
111|		return_if_error(lzma_next_filter_init(&coder->lzma,
112|				allocator, filters));
113|
114|		// Pass one dummy 0x00 byte to the LZMA decoder since that
115|		// is what it expects the first byte to be.
116|		const uint8_t dummy_in = 0;
117|		size_t dummy_in_pos = 0;
118|		if (coder->lzma.code(coder->lzma.coder, allocator,
119|				&dummy_in, &dummy_in_pos, 1,
120|				out, out_pos, out_size, LZMA_RUN) != LZMA_OK)
121|			return LZMA_PROG_ERROR;
122|
123|		assert(dummy_in_pos == 1);
124|		coder->props_decoded = true;
125|	}
126|
127|	// The rest is normal LZMA decoding.
128|	lzma_ret ret = coder->lzma.code(coder->lzma.coder, allocator,
129|				in, in_pos, in_size,
130|				out, out_pos, out_size, action);
131|
132|	// Update the remaining compressed size.
133|	assert(coder->comp_size >= *in_pos - in_start);
134|	coder->comp_size -= *in_pos - in_start;
135|
136|	if (coder->uncomp_size_is_exact) {
137|		// After successful decompression of the complete stream
138|		// the compressed size must match.
139|		if (ret == LZMA_STREAM_END && coder->comp_size != 0)
140|			ret = LZMA_DATA_ERROR;
141|	} else {
142|		// Update the amount of output remaining.
143|		assert(coder->uncomp_size >= *out_pos - out_start);
144|		coder->uncomp_size -= *out_pos - out_start;
145|
146|		// - We must not get LZMA_STREAM_END because the stream
147|		//   shouldn't have EOPM.
148|		// - We must use uncomp_size to determine when to
149|		//   return LZMA_STREAM_END.
150|		if (ret == LZMA_STREAM_END)
151|			ret = LZMA_DATA_ERROR;
152|		else if (coder->uncomp_size == 0)
153|			ret = LZMA_STREAM_END;
154|	}
155|
156|	return ret;
157|}

91|static lzma_ret
92|microlzma_encoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
93|		const lzma_options_lzma *options)
94|{
95|	lzma_next_coder_init(&microlzma_encoder_init, next, allocator);
96|
97|	lzma_microlzma_coder *coder = next->coder;
98|
99|	if (coder == NULL) {
100|		coder = lzma_alloc(sizeof(lzma_microlzma_coder), allocator);
101|		if (coder == NULL)
102|			return LZMA_MEM_ERROR;
103|
104|		next->coder = coder;
105|		next->code = &microlzma_encode;
106|		next->end = &microlzma_encoder_end;
107|
108|		coder->lzma = LZMA_NEXT_CODER_INIT;
109|	}
110|
111|	// Encode the properties byte. Bitwise-negation of it will be the
112|	// first output byte.
113|	if (lzma_lzma_lclppb_encode(options, &coder->props))
114|		return LZMA_OPTIONS_ERROR;
115|
116|	// Initialize the LZMA encoder.
117|	const lzma_filter_info filters[2] = {
118|		{
119|			.id = LZMA_FILTER_LZMA1,
120|			.init = &lzma_lzma_encoder_init,
121|			.options = (void *)(options),
122|		}, {
123|			.init = NULL,
124|		}
125|	};
126|
127|	return lzma_next_filter_init(&coder->lzma, allocator, filters);
128|}

26|extern lzma_ret
27|lzma_delta_coder_init(lzma_next_coder *next, const lzma_allocator *allocator,
28|		const lzma_filter_info *filters)
29|{
30|	// Allocate memory for the decoder if needed.
31|	lzma_delta_coder *coder = next->coder;
32|	if (coder == NULL) {
33|		coder = lzma_alloc(sizeof(lzma_delta_coder), allocator);
34|		if (coder == NULL)
35|			return LZMA_MEM_ERROR;
36|
37|		next->coder = coder;
38|
39|		// End function is the same for encoder and decoder.
40|		next->end = &delta_coder_end;
41|		coder->next = LZMA_NEXT_CODER_INIT;
42|	}
43|
44|	// Validate the options.
45|	if (lzma_delta_coder_memusage(filters[0].options) == UINT64_MAX)
46|		return LZMA_OPTIONS_ERROR;
47|
48|	// Set the delta distance.
49|	const lzma_options_delta *opt = filters[0].options;
50|	coder->distance = opt->dist;
51|
52|	// Initialize the rest of the variables.
53|	coder->pos = 0;
54|	memzero(coder->history, LZMA_DELTA_DIST_MAX);
55|
56|	// Initialize the next decoder in the chain, if any.
57|	return lzma_next_filter_init(&coder->next, allocator, filters + 1);
58|}

540|extern lzma_ret
541|lzma_lz_encoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
542|		const lzma_filter_info *filters,
543|		lzma_ret (*lz_init)(lzma_lz_encoder *lz,
544|			const lzma_allocator *allocator,
545|			lzma_vli id, const void *options,
546|			lzma_lz_options *lz_options))
547|{
548|#if defined(HAVE_SMALL) && !defined(HAVE_FUNC_ATTRIBUTE_CONSTRUCTOR)
549|	// The CRC32 table must be initialized.
550|	lzma_crc32_init();
551|#endif
552|
553|	// Allocate and initialize the base data structure.
554|	lzma_coder *coder = next->coder;
555|	if (coder == NULL) {
556|		coder = lzma_alloc(sizeof(lzma_coder), allocator);
557|		if (coder == NULL)
558|			return LZMA_MEM_ERROR;
559|
560|		next->coder = coder;
561|		next->code = &lz_encode;
562|		next->end = &lz_encoder_end;
563|		next->update = &lz_encoder_update;
564|		next->set_out_limit = &lz_encoder_set_out_limit;
565|
566|		coder->lz.coder = NULL;
567|		coder->lz.code = NULL;
568|		coder->lz.end = NULL;
569|		coder->lz.options_update = NULL;
570|		coder->lz.set_out_limit = NULL;
571|
572|		// mf.size is initialized to silence Valgrind
573|		// when used on optimized binaries (GCC may reorder
574|		// code in a way that Valgrind gets unhappy).
575|		coder->mf.buffer = NULL;
576|		coder->mf.size = 0;
577|		coder->mf.hash = NULL;
578|		coder->mf.son = NULL;
579|		coder->mf.hash_count = 0;
580|		coder->mf.sons_count = 0;
581|
582|		coder->next = LZMA_NEXT_CODER_INIT;
583|	}
584|
585|	// Initialize the LZ-based encoder.
586|	lzma_lz_options lz_options;
587|	return_if_error(lz_init(&coder->lz, allocator,
588|			filters[0].id, filters[0].options, &lz_options));
589|
590|	// Setup the size information into coder->mf and deallocate
591|	// old buffers if they have wrong size.
592|	if (lz_encoder_prepare(&coder->mf, allocator, &lz_options))
593|		return LZMA_OPTIONS_ERROR;
594|
595|	// Allocate new buffers if needed, and do the rest of
596|	// the initialization.
597|	if (lz_encoder_init(&coder->mf, allocator, &lz_options))
598|		return LZMA_MEM_ERROR;
599|
600|	// Initialize the next filter in the chain, if any.
601|	return lzma_next_filter_init(&coder->next, allocator, filters + 1);
602|}

235|extern lzma_ret
236|lzma_simple_coder_init(lzma_next_coder *next, const lzma_allocator *allocator,
237|		const lzma_filter_info *filters,
238|		size_t (*filter)(void *simple, uint32_t now_pos,
239|			bool is_encoder, uint8_t *buffer, size_t size),
240|		size_t simple_size, size_t unfiltered_max,
241|		uint32_t alignment, bool is_encoder)
242|{
243|	// Allocate memory for the lzma_simple_coder structure if needed.
244|	lzma_simple_coder *coder = next->coder;
245|	if (coder == NULL) {
246|		// Here we allocate space also for the temporary buffer. We
247|		// need twice the size of unfiltered_max, because then it
248|		// is always possible to filter at least unfiltered_max bytes
249|		// more data in coder->buffer[] if it can be filled completely.
250|		coder = lzma_alloc(sizeof(lzma_simple_coder)
251|				+ 2 * unfiltered_max, allocator);
252|		if (coder == NULL)
253|			return LZMA_MEM_ERROR;
254|
255|		next->coder = coder;
256|		next->code = &simple_code;
257|		next->end = &simple_coder_end;
258|		next->update = &simple_coder_update;
259|
260|		coder->next = LZMA_NEXT_CODER_INIT;
261|		coder->filter = filter;
262|		coder->allocated = 2 * unfiltered_max;
263|
264|		// Allocate memory for filter-specific data structure.
265|		if (simple_size > 0) {
266|			coder->simple = lzma_alloc(simple_size, allocator);
267|			if (coder->simple == NULL)
268|				return LZMA_MEM_ERROR;
269|		} else {
270|			coder->simple = NULL;
271|		}
272|	}
273|
274|	if (filters[0].options != NULL) {
275|		const lzma_options_bcj *simple = filters[0].options;
276|		coder->now_pos = simple->start_offset;
277|		if (coder->now_pos & (alignment - 1))
278|			return LZMA_OPTIONS_ERROR;
279|	} else {
280|		coder->now_pos = 0;
281|	}
282|
283|	// Reset variables.
284|	coder->is_encoder = is_encoder;
285|	coder->end_was_reached = false;
286|	coder->pos = 0;
287|	coder->filtered = 0;
288|	coder->size = 0;
289|
290|	return lzma_next_filter_init(&coder->next, allocator, filters + 1);
291|}

